using System; using System.ComponentModel; using System.Windows.Forms; using Inventory.Contracts;
namespace Inventory.Client { internal sealed class SaleForm:Form { private readonly Func<IInventoryGateway> _factory; private readonly int _user,_branch; private readonly BindingList<SaleLine> _cart=new BindingList<SaleLine>(); private readonly TextBox _product=new TextBox{Width=60};private readonly TextBox _quantity=new TextBox{Width=60};private readonly DataGridView _grid=new DataGridView{Dock=DockStyle.Fill,AutoGenerateColumns=true}; public SaleForm(Func<IInventoryGateway> factory,int user,int branch){_factory=factory;_user=user;_branch=branch;Text="Venta - Sucursal "+branch;Width=560;Height=390;_grid.DataSource=_cart;var add=new Button{Text="Agregar",AutoSize=true};var remove=new Button{Text="Quitar",AutoSize=true};var checkout=new Button{Text="Confirmar venta",AutoSize=true};add.Click+=(s,e)=>{if(int.TryParse(_product.Text,out int p)&&int.TryParse(_quantity.Text,out int q)&&q>0){_cart.Add(new SaleLine{ProductId=p,Quantity=q});_product.Clear();_quantity.Clear();}else MessageBox.Show("Captura producto y cantidad válidos.");};remove.Click+=(s,e)=>{if(_grid.CurrentRow?.DataBoundItem is SaleLine line)_cart.Remove(line);};checkout.Click+=(s,e)=>{try{int id=_factory().RegisterSale(_user,_branch,new System.Collections.Generic.List<SaleLine>(_cart).ToArray());MessageBox.Show("Venta #"+id+" registrada.");_cart.Clear();}catch(Exception ex){MessageBox.Show(ex.Message,"Venta",MessageBoxButtons.OK,MessageBoxIcon.Warning);}};var top=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,Padding=new Padding(8)};top.Controls.AddRange(new Control[]{new Label{Text="Producto ID",AutoSize=true,Padding=new Padding(0,6,0,0)},_product,new Label{Text="Cantidad",AutoSize=true,Padding=new Padding(0,6,0,0)},_quantity,add,remove,checkout});Controls.Add(_grid);Controls.Add(top);} } }
